const sheetProductVariants=[
  {id:'flat',name:'床单',hint:'轻薄单层 · 自然垂边',spec:'床单类别：单件轻薄单层平床单，窄折边缝线，床尾和两侧自然下垂、柔软重力褶皱，无松紧包角、夹棉或绗缝。'},
  {id:'fitted',name:'床笠',hint:'松紧包角 · 贴合床垫',spec:'床单类别：单件无夹棉床笠，薄型无绗缝床面、连体侧围与缝合包角，底缘松紧收拢并包入床垫底部，贴合床垫，无下垂床裙。'},
  {id:'quilted',name:'夹棉床笠',hint:'薄夹棉绗缝 · 松紧包覆',spec:'床单类别：单件夹棉床笠，床面薄夹棉、浅菱格绗缝，连体单层无夹棉侧围、缝合包角，底缘松紧包入床垫，低蓬松贴合，不是被芯、厚床垫或床裙。'}
];
function currentSheetProductVariant(){return sheetProductVariants.find(v=>v.id===state.sheetVariant)||sheetProductVariants[0]}
function sheetProductSpecification(){return currentSheetProductVariant().spec}
function sheetProductNotes(){return ' 单件'+currentSheetProductVariant().name+'，结构以类别为准；质感只改变表面织纹、绒毛、光泽，不改变夹棉和包覆结构。配拍2只套有枕套的睡枕，不添加被子或第二件床面产品。枕套正面A、反面B；仅A时枕套全部A。仅A全件用A；同时上传A/B则整件床单或床笠沿用床单规则用B，侧围和底边一致。示例图只示意机位，不复制示例白色。'}
function sheetProductAngleName(angle,variant=state.sheetVariant){const fitted=variant==='fitted'||variant==='quilted';return {reverse:fitted?'松紧角展示':'翻边看反面',pillowclose:fitted?'松紧角特写':'床单包边特写',drape:fitted?'侧围贴合':'床边垂坠'}[angle.id]||angle.name}
const sheetVariantPanel=document.createElement('section');sheetVariantPanel.id='sheetVariantPanel';sheetVariantPanel.className='set-variant-flyout quilt-variant-flyout sheet-variant-flyout';sheetVariantPanel.hidden=true;sheetVariantPanel.setAttribute('aria-labelledby','sheetVariantTitle');
sheetVariantPanel.innerHTML='<div class="set-variant-heading"><div><h2 id="sheetVariantTitle">床单 / 床笠</h2><p>选择铺设结构 · 默认床单</p></div><button type="button" class="set-variant-close" aria-label="收起床单床笠分类">×</button></div><div class="set-variant-options"><h3>产品类别</h3><div class="set-variant-grid" role="group" aria-label="床单或床笠类别"></div></div><div class="set-variant-footer"><span id="sheetVariantSelected"></span><button type="button" class="set-variant-done">完成选择</button></div>';
document.body.append(sheetVariantPanel);
function renderSheetVariantControl(){const trigger=document.querySelector('[data-product="sheet"]');if(trigger){trigger.classList.add('has-sheet-variants');trigger.setAttribute('aria-expanded',String(!sheetVariantPanel.hidden));trigger.setAttribute('aria-controls','sheetVariantPanel');trigger.title=currentSheetProductVariant().name+' · 点击展开床单床笠分类';renderChosenProductLabel(trigger,'床单 / 床笠',currentSheetProductVariant().name);}if(state.product==='sheet'){$('partsHint').textContent='1 件'+currentSheetProductVariant().name+' + 2 只配套枕套 · '+currentSheetProductVariant().hint;document.querySelector('.group-angles .group-purpose').textContent=currentSheetProductVariant().name+'构图 · 可多选 · AI 示例';}sheetVariantPanel.querySelector('#sheetVariantSelected').textContent='已选：'+currentSheetProductVariant().name;}
function closeSheetVariants(returnFocus=false){sheetVariantPanel.hidden=true;renderSheetVariantControl();if(returnFocus)document.querySelector('[data-product="sleepbag"]')?.focus()}
function placeSheetVariants(){placeProductSubmenu(sheetVariantPanel,document.querySelector('[data-product="sheet"]'),510);}
function selectSheetProductVariant(id){if(state.busy||state.product!=='sheet'||!sheetProductVariants.some(v=>v.id===id))return;(state.productVariantChoices??={}).sheet=true;state.sheetVariant=id;sheetVariantPanel.querySelectorAll('[data-sheet-variant]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.sheetVariant===id)));renderSheetVariantControl();renderSelections();if(typeof closeSheetVariants==='function')closeSheetVariants(true);}
function openSheetVariants(){if(state.busy||state.product!=='sheet')return;const grid=sheetVariantPanel.querySelector('.set-variant-grid');grid.replaceChildren();for(const item of sheetProductVariants){const button=document.createElement('button');button.type='button';button.className='set-variant-option illustrated-variant-option';button.dataset.sheetVariant=item.id;button.setAttribute('aria-pressed',String(currentSheetProductVariant().id===item.id));const picture=document.createElement('span');picture.className='product-variant-preview';picture.style.backgroundImage="url('/assets/sheet-"+item.id+"-angles-v3-framed.png')";picture.setAttribute('role','img');picture.setAttribute('aria-label',item.name+' AI 结构示例');const name=document.createElement('strong');name.textContent=item.name;const hint=document.createElement('small');hint.textContent=item.hint;button.append(picture,name,hint);button.addEventListener('click',()=>selectSheetProductVariant(item.id));grid.append(button)}sheetVariantPanel.hidden=false;placeSheetVariants();renderSheetVariantControl();}
sheetVariantPanel.querySelector('.set-variant-close').onclick=()=>closeSheetVariants(true);sheetVariantPanel.querySelector('.set-variant-done').onclick=()=>closeSheetVariants(true);
document.addEventListener('click',e=>{const product=e.target.closest('[data-product]');if(product&&!state.busy){if(product.dataset.product==='sheet'){if(sheetVariantPanel.hidden)openSheetVariants();else closeSheetVariants()}else closeSheetVariants();renderSheetVariantControl();return;}if(!sheetVariantPanel.contains(e.target))closeSheetVariants();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!sheetVariantPanel.hidden)closeSheetVariants(true);if(e.key==='ArrowDown'&&e.target.closest('[data-product="sheet"]')&&!state.busy){e.preventDefault();openSheetVariants();sheetVariantPanel.querySelector('[aria-pressed=true]')?.focus();}});
window.addEventListener('resize',()=>closeSheetVariants());window.addEventListener('scroll',e=>{if(!sheetVariantPanel.contains(e.target))closeSheetVariants()},{passive:true,capture:true});
new MutationObserver(renderSheetVariantControl).observe($('products'),{childList:true});new MutationObserver(()=>{if(state.busy)closeSheetVariants();renderSheetVariantControl()}).observe($('generateBtn'),{attributes:true,attributeFilter:['disabled']});renderSheetVariantControl();
